import re

def validate_policy_id(policy_id: str) -> bool:
    """Validate corporate policy identifier against format 'POL-{DEPT}-{NUM}'."""
    pattern = r'^POL-(HR|IT|LEG|FIN|SEC|OPS)-[0-9]{3}$'
    return bool(re.match(pattern, policy_id.strip()))

import re
import string

def sanitize_document_text(text: str) -> str:
    """Sanitize text by stripping control characters and normalizing whitespace."""
    if not text:
        return ""
    printable = set(string.printable)
    filtered = ''.join(c for c in text if c in printable)
    normalized = re.sub(r'\n{3,}', '\n\n', filtered)
    return normalized.strip()
